cd /tmp && python -c "
import json
s=json.load(open('/mnt/session/uploads/ledger/report_schema.json'));d=json.load(open('/mnt/session/outputs/report.json'))
T={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int}
def v(sc,x,p='$'):
    t=sc.get('type')
    if t and not isinstance(x,T[t]) or (t=='integer' and isinstance(x,bool)): print('type',p)
    if t=='object':
        for k in sc.get('required',[]):
            if k not in x: print('missing',p,k)
        for k in x:
            if k not in sc.get('properties',{}): print('extra',p,k)
            else: v(sc['properties'][k],x[k],p+'.'+k)
    if t=='array' and 'items' in sc:
        for i,e in enumerate(x): v(sc['items'],e,p+f'[{i}]')
v(s,d);print('done')"
